static const uint16_t kGameSpritesCount = 28;

inline const GameSprite* FindGameSpriteByName(const char* name) {
  if (name == nullptr) return nullptr;
  for (uint16_t i = 0; i < kGameSpritesCount; ++i) {
    const char* s = kGameSprites[i].name;
    uint16_t j = 0;
    for (;; ++j) {
      if (s[j] != name[j]) break;
      if (s[j] == 0) return &kGameSprites[i];
    }
  }
  return nullptr;
}
